SObject row = new Account(Name = 'Child');
row.put('Id', '001000000000001AAA');
System.assertEquals('Child', row.get('Name'));
System.assert(row.isSet('Name'));
System.assert(row.getPopulatedFieldsAsMap().containsKey('Name'));
System.assert(row.equals(row));
SObject cloneNoId = row.clone();
System.assertEquals(null, cloneNoId.get('Id'));
System.assertEquals('Child', cloneNoId.get('Name'));
SObject cloneOne = row.clone(false);
System.assertEquals(null, cloneOne.get('Id'));
row.put('Name', 'Changed');
System.assertEquals('Changed', row.get('Name'));
row.clear();
System.assert(!row.isSet('Name'));
Account parent = new Account(Name = 'Parent');
row.putSObject('Parent', parent);
System.assertEquals('Parent', row.getSObject('Parent').get('Name'));
row.put('Contacts', new List<Contact>{new Contact(LastName = 'Smith')});
System.assertEquals(1, row.getSObjects('Contacts').size());

